WITH web_events_by_session AS (SELECT session_id, ROUND(AVG(duration_sec), 2) avg_duration_sec, ROUND(STDDEV(duration_sec), 2) stddev_duration_sec FROM web_events GROUP BY session_id) SELECT s.id, s.device, s.customer_id, webs.avg_duration_sec, webs.stddev_duration_sec FROM sessions s JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.stddev_duration_sec > 46 ORDER BY device DESC, id LIMIT 3;
